(()=>{"use strict";self.onmessage=s=>{const{type:i,data:e,messageId:o}=s.data;switch(i){case"CHECK_ISKANDER_COLLISIONS":!function(s,i,e){const o=[];if(i.isDestroyed)self.postMessage({type:"ISKANDER_COLLISION_RESULT",data:{collisions:o},messageId:e});else{for(const e of s)if(e.isLaunched&&!e.hasExploded){const s=i.position.x-e.position.x,t=i.position.y-e.position.y,a=i.position.z-e.position.z,d=s*s+t*t+a*a;if(d<=64){const s=Math.sqrt(d);o.push({missileId:e.id,collisionType:"direct_hit",distance:s,damage:50,shouldExplode:!0})}else if(d<=400){const s=Math.sqrt(d),i=Math.max(10,40-s);o.push({missileId:e.id,collisionType:"proximity",distance:s,damage:i,shouldExplode:!0})}}self.postMessage({type:"ISKANDER_COLLISION_RESULT",data:{collisions:o},messageId:e})}}(e.iskanderMissiles,e.bomberData,o);break;case"CHECK_DEFENSE_COLLISIONS":!function(s,i,e){const o=[];if(i.isDestroyed)self.postMessage({type:"DEFENSE_COLLISION_RESULT",data:{collisions:o},messageId:e});else{for(const e of s)if(e.isLaunched&&!e.hasExploded){const s=i.position.x-e.position.x,t=i.position.y-e.position.y,a=i.position.z-e.position.z,d=s*s+t*t+a*a;if(d<=64){const s=Math.sqrt(d);o.push({missileId:e.id,collisionType:"direct_hit",distance:s,damage:25,shouldExplode:!0})}else if(d<=400){const s=Math.sqrt(d),i=Math.max(5,20-s);o.push({missileId:e.id,collisionType:"proximity",distance:s,damage:i,shouldExplode:!0})}}self.postMessage({type:"DEFENSE_COLLISION_RESULT",data:{collisions:o},messageId:e})}}(e.defenseMissiles,e.bomberData,o)}}})();